    X['a'][pv,hc] += 1.0 * np.einsum('aUbV,VWUX,bXiW->ai', h['ab'][v,A,v,A], lambdas['bb'], t['ab'][pv,pA,hc,hA], optimize=True)
    X['a'][pv,hc] += 1.0 * np.einsum('IA,aAiI->ai', h['b'][C,V], t['ab'][pv,pV,hc,hC], optimize=True)
    X['a'][pv,hc] += 0.5 * np.einsum('IUVW,VWUX,aXiI->ai', h['bb'][C,A,A,A], lambdas['bb'], t['ab'][pv,pA,hc,hC], optimize=True)
    X['a'][pv,hc] += 0.5 * np.einsum('UVWA,WXUV,aAiX->ai', h['bb'][A,A,A,V], lambdas['bb'], t['ab'][pv,pV,hc,hA], optimize=True)
    ### T3 Parts ###
    # A|V
    X['b'][pV,hA] += 0.25 * np.einsum('uv,wx,ijuw,vxAijU->AU', eta1['a'], eta1['a'], h['aa'][c,c,a,a], t['aab'][pa,pa,pV,hc,hc,hA], optimize=True)
    X['b'][pV,hA] += 1.0 * np.einsum('uv,wx,ixua,vaAiwU->AU', eta1['a'], gamma1['a'], h['aa'][c,a,a,v], t['aab'][pa,pv,pV,hc,ha,hA], optimize=True)
    X['b'][pV,hA] += -1.0 * np.einsum('uv,wx,xIuB,vABwIU->AU', eta1['a'], gamma1['a'], h['ab'][a,C,a,V], t['abb'][pa,pV,pV,ha,hC,hA], optimize=True)
    X['b'][pV,hA] += 1.0 * np.einsum('uv,VW,iWuB,vABiUV->AU', eta1['a'], gamma1['b'], h['ab'][c,A,a,V], t['abb'][pa,pV,pV,hc,hA,hA], optimize=True)
    X['b'][pV,hA] += 0.5 * np.einsum('uv,ijua,vaAijU->AU', eta1['a'], h['aa'][c,c,a,v], t['aab'][pa,pv,pV,hc,hc,hA], optimize=True)
    X['b'][pV,hA] += -1.0 * np.einsum('uv,iIuB,vABiIU->AU', eta1['a'], h['ab'][c,C,a,V], t['abb'][pa,pV,pV,hc,hC,hA], optimize=True)
    X['b'][pV,hA] += 1.0 * np.einsum('VW,uv,iIuV,vWAiIU->AU', eta1['b'], eta1['a'], h['ab'][c,C,a,A], t['abb'][pa,pA,pV,hc,hC,hA], optimize=True)
    X['b'][pV,hA] += 0.25 * np.einsum('VW,XY,IJVX,WYAIJU->AU', eta1['b'], eta1['b'], h['bb'][C,C,A,A], t['bbb'][pA,pA,pV,hC,hC,hA], optimize=True)
    X['b'][pV,hA] += 1.0 * np.einsum('VW,uv,vIaV,aWAuIU->AU', eta1['b'], gamma1['a'], h['ab'][a,C,v,A], t['abb'][pv,pA,pV,ha,hC,hA], optimize=True)
    X['b'][pV,hA] += -1.0 * np.einsum('VW,XY,iYaV,aWAiUX->AU', eta1['b'], gamma1['b'], h['ab'][c,A,v,A], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
