    X['bb'][pA,pV,hC,hC] += 1.0 * np.einsum('VW,WI,UAJV->UAIJ', gamma1['b'], h['b'][A,C], t['bb'][pA,pV,hC,hA], optimize=True)
    X['bb'][pA,pV,hC,hC] += 1.0 * np.einsum('VW,WAIB,UBJV->UAIJ', gamma1['b'], h['bb'][A,V,C,V], t['bb'][pA,pV,hC,hA], optimize=True)
