    X['bb'][pV,pV,hC,hC] += 0.5 * np.einsum('UV,VAIJ,BU->ABIJ', eta1['b'], h['bb'][A,V,C,C], t['b'][pV,hA], optimize=True)
    X['bb'][pV,pV,hC,hC] += 0.5 * np.einsum('UV,AU,VBIJ->ABIJ', eta1['b'], h['b'][V,A], t['bb'][pA,pV,hC,hC], optimize=True)
