    X['bb'][pV,pV,hC,hC] += -0.125 * np.einsum('UV,WX,ABUW,VXIJ->ABIJ', gamma1['b'], gamma1['b'], h['bb'][V,V,A,A], t['bb'][pA,pA,hC,hC], optimize=True)
