    X['bb'][pV,pV,hC,hC] += -1.0 * np.einsum('KAIC,BCJK->ABIJ', h['bb'][C,V,C,V], t['bb'][pV,pV,hC,hC], optimize=True)
    X['bb'][pV,pV,hC,hC] += -0.5 * np.einsum('AC,BCIJ->ABIJ', h['b'][V,V], t['bb'][pV,pV,hC,hC], optimize=True)
