    X['ab'][pv,pA,ha,hA] += 1.0 * np.einsum('vw,xy,wUxV,yauv->aUuV', eta1['a'], gamma1['a'], h['ab'][a,A,a,A], t['aa'][pa,pv,ha,ha], optimize=True)
