    # cc|va
    X['aa'][pa,pv,hc,hc] += 0.25 * np.einsum('vw,xy,uavx,wyij->uaij', eta1['a'], eta1['a'], h['aa'][a,v,a,a], t['aa'][pa,pa,hc,hc], optimize=True)
