    X['aa'][pa,pv,hc,hc] += -1.0 * np.einsum('UV,WX,uViW,aXjU->uaij', eta1['b'], gamma1['b'], h['ab'][a,A,c,A], t['ab'][pv,pA,hc,hA], optimize=True)
