    X['aa'][pa,pv,hc,hc] += 1.0 * np.einsum('UV,WX,aViW,uXjU->uaij', eta1['b'], gamma1['b'], h['ab'][v,A,c,A], t['ab'][pa,pA,hc,hA], optimize=True)
