    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('aIiA,bAjI->abij', h['ab'][v,C,c,V], t['ab'][pv,pV,hc,hC], optimize=True)
    ### T3 Parts ###
    # AA|VA
    X['bb'][pA,pV,hA,hA] += -1.0 * np.einsum('uv,iIuU,vVAiIW->VAUW', eta1['a'], h['ab'][c,C,a,A], t['abb'][pa,pA,pV,hc,hC,hA], optimize=True)
