    X['bb'][pA,pV,hA,hA] += 0.5 * np.einsum('XY,iUaX,aYAiVW->UAVW', eta1['b'], h['ab'][c,A,v,A], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
