    X['bb'][pA,pV,hA,hA] += -1.0 * np.einsum('uv,vIaU,aVAuIW->VAUW', gamma1['a'], h['ab'][a,C,v,A], t['abb'][pv,pA,pV,ha,hC,hA], optimize=True)
    X['bb'][pA,pV,hA,hA] += -0.5 * np.einsum('uv,vUaB,aABuVW->UAVW', gamma1['a'], h['ab'][a,A,v,V], t['abb'][pv,pV,pV,ha,hA,hA], optimize=True)
    X['bb'][pA,pV,hA,hA] += 1.0 * np.einsum('XY,iYaU,aVAiWX->VAUW', gamma1['b'], h['ab'][c,A,v,A], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
