    X['bb'][pA,pV,hA,hA] += -0.25 * np.einsum('XY,UYBC,ABCVWX->UAVW', gamma1['b'], h['bb'][A,A,V,V], t['bbb'][pV,pV,pV,hA,hA,hA], optimize=True)
    X['bb'][pA,pV,hA,hA] += 0.5 * np.einsum('ia,aUAiVW->UAVW', h['a'][c,v], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
    X['bb'][pA,pV,hA,hA] += -1.0 * np.einsum('iIaU,aVAiIW->VAUW', h['ab'][c,C,v,A], t['abb'][pv,pA,pV,hc,hC,hA], optimize=True)
    X['bb'][pA,pV,hA,hA] += -0.5 * np.einsum('iUaB,aABiVW->UAVW', h['ab'][c,A,v,V], t['abb'][pv,pV,pV,hc,hA,hA], optimize=True)
