    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aUiA,VWUX,bXAjVW->abij', h['ab'][v,A,c,V], lambdas['bb'], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aUuA,uVvU,vbAijV->abij', h['ab'][v,A,a,V], lambdas['ab'], t['aab'][pa,pv,pV,hc,hc,hA], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aUcV,uVvU,vbciju->abij', h['ab'][v,A,v,A], lambdas['ab'], t['aaa'][pa,pv,pv,hc,hc,ha], optimize=True)
