    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('uv,kaiu,bk,vj->abij', gamma1['a'], h['aa'][c,v,c,a], t['a'][pv,hc], t['a'][pa,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('uv,kauc,vi,bcjk->abij', gamma1['a'], h['aa'][c,v,a,v], t['a'][pa,hc], t['aa'][pv,pv,hc,hc], optimize=True)
