    X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('uv,vc,au,bcij->abij', gamma1['a'], h['a'][a,v], t['a'][pv,ha], t['aa'][pv,pv,hc,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('uv,vc,ci,abju->abij', gamma1['a'], h['a'][a,v], t['a'][pv,hc], t['aa'][pv,pv,hc,ha], optimize=True)
    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('uv,vaic,bu,cj->abij', gamma1['a'], h['aa'][a,v,c,v], t['a'][pv,ha], t['a'][pv,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += 0.25 * np.einsum('uv,vacd,bu,cdij->abij', gamma1['a'], h['aa'][a,v,v,v], t['a'][pv,ha], t['aa'][pv,pv,hc,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('uv,vacd,ci,bdju->abij', gamma1['a'], h['aa'][a,v,v,v], t['a'][pv,hc], t['aa'][pv,pv,hc,ha], optimize=True)
