    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('uv,vIcA,aAiI,bcju->abij', gamma1['a'], h['ab'][a,C,v,V], t['ab'][pv,pV,hc,hC], t['aa'][pv,pv,hc,ha], optimize=True)
