    X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('UV,kVcA,cAiU,abjk->abij', gamma1['b'], h['ab'][c,A,v,V], t['ab'][pv,pV,hc,hA], t['aa'][pv,pv,hc,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('UV,aVcA,ci,bAjU->abij', gamma1['b'], h['ab'][v,A,v,V], t['a'][pv,hc], t['ab'][pv,pV,hc,hA], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('UV,aVcA,AU,bcij->abij', gamma1['b'], h['ab'][v,A,v,V], t['b'][pV,hA], t['aa'][pv,pv,hc,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('UV,IVAB,aAiU,bBjI->abij', gamma1['b'], h['bb'][C,A,V,V], t['ab'][pv,pV,hc,hA], t['ab'][pv,pV,hc,hC], optimize=True)
    X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('kc,ak,bcij->abij', h['a'][c,v], t['a'][pv,hc], t['aa'][pv,pv,hc,hc], optimize=True)
