    X['aa'][pv,pv,hc,hc] += 0.25 * np.einsum('klij,ak,bl->abij', h['aa'][c,c,c,c], t['a'][pv,hc], t['a'][pv,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('klic,ak,bcjl->abij', h['aa'][c,c,c,v], t['a'][pv,hc], t['aa'][pv,pv,hc,hc], optimize=True)
