    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('aIcA,ci,bAjI->abij', h['ab'][v,C,v,V], t['a'][pv,hc], t['ab'][pv,pV,hc,hC], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('aIcA,AI,bcij->abij', h['ab'][v,C,v,V], t['b'][pV,hC], t['aa'][pv,pv,hc,hc], optimize=True)
    X['aa'][pv,pv,hc,hc] += 0.5 * np.einsum('IJAB,aAiI,bBjJ->abij', h['bb'][C,C,V,V], t['ab'][pv,pV,hc,hC], t['ab'][pv,pV,hc,hC], optimize=True)
    ### T3 Parts ###
    # AA|VA
    X['bb'][pA,pV,hA,hA] += 0.5 * np.einsum('ijab,ai,bUAjVW->UAVW', h['aa'][c,c,v,v], t['a'][pv,hc], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
