    X['bb'][pA,pV,hA,hA] += 0.5 * np.einsum('IJBC,BI,UACJVW->UAVW', h['bb'][C,C,V,V], t['b'][pV,hC], t['bbb'][pA,pV,pV,hC,hA,hA], optimize=True)
    # AA|VV
    X['bb'][pV,pV,hA,hA] += -0.25 * np.einsum('uv,ijua,ai,vABjUV->ABUV', eta1['a'], h['aa'][c,c,a,v], t['a'][pv,hc], t['abb'][pa,pV,pV,hc,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += 0.5 * np.einsum('uv,iIuC,AI,vBCiUV->ABUV', eta1['a'], h['ab'][c,C,a,V], t['b'][pV,hC], t['abb'][pa,pV,pV,hc,hA,hA], optimize=True)
