    X['bb'][pV,pV,hA,hA] += 0.25 * np.einsum('WX,iIaW,ai,XABIUV->ABUV', eta1['b'], h['ab'][c,C,v,A], t['a'][pv,hc], t['bbb'][pA,pV,pV,hC,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += -0.5 * np.einsum('WX,iIaW,AI,aXBiUV->ABUV', eta1['b'], h['ab'][c,C,v,A], t['b'][pV,hC], t['abb'][pv,pA,pV,hc,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += -0.5 * np.einsum('WX,IJWC,AI,XBCJUV->ABUV', eta1['b'], h['bb'][C,C,A,V], t['b'][pV,hC], t['bbb'][pA,pV,pV,hC,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += -0.25 * np.einsum('WX,IJWC,CI,XABJUV->ABUV', eta1['b'], h['bb'][C,C,A,V], t['b'][pV,hC], t['bbb'][pA,pV,pV,hC,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += -0.25 * np.einsum('uv,ivab,bi,aABuUV->ABUV', gamma1['a'], h['aa'][c,a,v,v], t['a'][pv,hc], t['abb'][pv,pV,pV,ha,hA,hA], optimize=True)
    X['bb'][pV,pV,hA,hA] += 0.5 * np.einsum('uv,vIaC,AI,aBCuUV->ABUV', gamma1['a'], h['ab'][a,C,v,V], t['b'][pV,hC], t['abb'][pv,pV,pV,ha,hA,hA], optimize=True)
