    X['bb'][pV,pV,hA,hA] += -0.25 * np.einsum('WX,IXCD,DI,ABCUVW->ABUV', gamma1['b'], h['bb'][C,A,V,V], t['b'][pV,hC], t['bbb'][pV,pV,pV,hA,hA,hA], optimize=True)
