    X['aa'][pv,pv,hc,hc] += 0.25 * np.einsum('kauc,uvwx,bk,wxcijv->abij', h['aa'][c,v,a,v], lambdas['aa'], t['a'][pv,hc], t['aaa'][pa,pa,pv,hc,hc,ha], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('kauc,uvwx,ci,wxbjkv->abij', h['aa'][c,v,a,v], lambdas['aa'], t['a'][pv,hc], t['aaa'][pa,pa,pv,hc,hc,ha], optimize=True)
    X['aa'][pv,pv,hc,hc] += -0.5 * np.einsum('kauc,uUvV,bk,vcVijU->abij', h['aa'][c,v,a,v], lambdas['ab'], t['a'][pv,hc], t['aab'][pa,pv,pA,hc,hc,hA], optimize=True)
    X['aa'][pv,pv,hc,hc] += 1.0 * np.einsum('kauc,uUvV,ci,vbVjkU->abij', h['aa'][c,v,a,v], lambdas['ab'], t['a'][pv,hc], t['aab'][pa,pv,pA,hc,hc,hA], optimize=True)
    X['aa'][pv,pv,hc,hc] += -1.0 * np.einsum('kIiU,uUvV,ak,vbVjuI->abij', h['ab'][c,C,c,A], lambdas['ab'], t['a'][pv,hc], t['aab'][pa,pv,pA,hc,ha,hC], optimize=True)
