    X['aa'][pv,pv,hc,hc] += -0.25 * np.einsum('kIuA,uUvV,vVkU,abAijI->abij', h['ab'][c,C,a,V], lambdas['ab'], t['ab'][pa,pA,hc,hA], t['aab'][pv,pv,pV,hc,hc,hC], optimize=True)
